(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.WHYChatView=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses={superseded:'訂正前',withdrawn:'訂正により無効',sending:'送信中',sent:'送信済み',failed:'送信失敗',stopped:'停止しました'};
function message(m,referenceHTML=()=> ''){const user=m.role==='user',source=m.source==='openai-responses'?'実AIで受信した応答':m.source==='loopback-fixture'?'ローカル試験・実AIではない':m.role==='assistant'?'取り込んだ履歴・出典未検証':'本人の入力 / 取り込み履歴';const state=m.status!=='current'?statuses[m.status]:(statuses[m.delivery]||'');
return '<article class="chat-message '+(user?'user':'assistant')+' '+esc(m.status)+'" data-message-id="'+esc(m.id)+'" aria-label="'+(user?'あなた':'COACH')+'の発言">'+(!user?'<span class="coach-avatar" aria-hidden="true"></span><p class="coach-name">COACH</p>':'')+'<div class="bubble"><p class="message-text">'+esc(m.text)+'</p></div><div class="message-footer">'+(state?'<span class="delivery-state '+esc(m.delivery||m.status)+'">'+esc(state)+'</span>':'')+'<details class="message-menu"><summary aria-label="'+(user?'あなた':'COACH')+'の発言の詳細">詳細</summary><div class="message-detail"><p>'+esc(source)+'</p>'+(m.createdAt?'<p>'+esc(m.createdAt)+'</p>':'')+(m.status!=='current'?'<p>'+esc(statuses[m.status]||m.status)+'</p>':'')+(m.delivery==='failed'?'<p>応答を表示できませんでした。外部受信の有無は、この表示だけでは判断できません。</p>':'')+(user&&m.status==='current'?'<button type="button" data-live-edit="'+esc(m.id)+'">この発言を訂正</button>':'')+(m.metadata?'<p>HTTP '+esc(m.metadata.httpStatus)+' / input '+esc(m.metadata.usage?.input_tokens??'未取得')+'・output '+esc(m.metadata.usage?.output_tokens??'未取得')+' tokens</p><p>通信成功と対話品質は別に評価します。</p>':'')+(m.metadata?.validationWarnings?.length?'<p>未確認の抽出・分類は保留または除外しました。</p>':'')+(m.references?.length?'<details><summary>引用・根拠候補</summary>'+m.references.map(referenceHTML).join('')+'</details>':'')+'</div></details></div></article>';}
return{message};});
